#!/usr/bin/env python3
"""Export Hugo docs/ as an Obsidian vault with wikilinks."""
import os
import re
import shutil
import sys

SRC = "docs"
OUT = "obsidian-vault"

# ---------- build URL -> note id map ----------
url_map = {}
notes = []  # (relpath, note_id)

for root, _dirs, files in os.walk(SRC):
    for name in files:
        if not name.endswith(".md"):
            continue
        full = os.path.join(root, name)
        rel = os.path.relpath(full, ".")          # docs/a/b.md
        note_id = rel[:-3]                         # docs/a/b
        notes.append((rel, note_id))
        stem = note_id
        if os.path.basename(stem) == "_index":
            base = os.path.dirname(stem)           # docs/a
            for u in ("/" + base + "/", "/" + base,
                      "/" + base + "/index", "/" + base + "/index/"):
                url_map.setdefault(u, note_id)
        else:
            for u in ("/" + stem + "/", "/" + stem):
                url_map.setdefault(u, note_id)

def resolve(url):
    """Return note_id for a site URL, or None."""
    url = url.split("#", 1)[0].split("?", 1)[0]
    if not url:
        return None
    if url in url_map:
        return url_map[url]
    for cand in (url, url + "/", url.rstrip("/")):
        if cand in url_map:
            return url_map[cand]
    if url.endswith(".md"):
        return url_map.get(url[:-3]) or url_map.get(url[:-3] + "/")
    return None

# ---------- per-file conversion ----------
md_link = re.compile(r"\[([^\]]*)\]\((/docs/[^)\s#]+)(#[^)]*)?\)")
shortcode = re.compile(r"\{\{[<%]\s*(?:relref|ref)\s+\"([^\"]+)\"\s*[>%]\}\}")
wiki = re.compile(r"\[\[([^]|#]+)")

def get_title(text):
    m = re.match(r"^---\s*$.*?^---\s*$", text, re.S | re.M)
    if not m:
        return None
    fm = m.group(0)
    t = re.search(r"^title:\s*[\"']?(.+?)[\"']?\s*$", fm, re.M)
    return t.group(1).strip() if t else None

stats = {"notes": 0, "md_conv": 0, "sc_conv": 0, "unresolved": 0}
unresolved_samples = []

def convert(text, rel):
    def md_sub(m):
        label, url, anchor = m.group(1), m.group(2), m.group(3) or ""
        target = resolve(url)
        if not target:
            stats["unresolved"] += 1
            if len(unresolved_samples) < 10:
                unresolved_samples.append(f"{rel} -> {url}")
            return m.group(0)
        stats["md_conv"] += 1
        return f"[[{target}{anchor}|{label}]]"

    def sc_sub(m):
        url = m.group(1)
        target = resolve(url)
        if not target:
            stats["unresolved"] += 1
            if len(unresolved_samples) < 10:
                unresolved_samples.append(f"{rel} -> {url}")
            return m.group(0)
        stats["sc_conv"] += 1
        return f"[[{target}]]"

    text = md_link.sub(md_sub, text)
    text = shortcode.sub(sc_sub, text)
    return text

if os.path.exists(OUT):
    shutil.rmtree(OUT)

for rel, note_id in notes:
    with open(rel, encoding="utf-8") as f:
        text = f.read()
    new = convert(text, rel)
    dest = os.path.join(OUT, rel)
    os.makedirs(os.path.dirname(dest), exist_ok=True)
    with open(dest, "w", encoding="utf-8") as f:
        f.write(new)
    stats["notes"] += 1

# Obsidian config so graph ignores nothing by default
os.makedirs(os.path.join(OUT, ".obsidian"), exist_ok=True)
with open(os.path.join(OUT, ".obsidian", "app.json"), "w") as f:
    f.write('{\n  "useMarkdownLinks": false,\n  "newLinkFormat": "absolute"\n}\n')

print(stats)
for s in unresolved_samples:
    print("UNRESOLVED:", s)

